/* ------------------------------------------------------------- labelling */

/** Normalize a raw injury string into a clean label. */
export function cleanInjuryLabel(raw: string): string {
  const base = raw.replace(/\s*\(.*\)\s*$/, "").trim();
  const key = base.toLowerCase();
  const map: Record<string, string> = {
    concussion: "Concussion",
    acl: "ACL / Knee",
    quad: "Quad",
    quadricep: "Quad",
    thumb: "Hand / Thumb",
    finger: "Hand / Finger",
    "turf toe": "Foot / Toe",
    toe: "Foot / Toe",
    foot: "Foot / Toe",
    rib: "Ribs",
    ribs: "Ribs",
    "ankle/shoulder": "Multiple / Ankle",
    undisclosed: "Unknown / Undisclosed",
    unknown: "Unknown / Undisclosed",
  };
  return map[key] || base;
}

const INJURY_CATEGORY_RULES: { category: string; keywords: string[] }[] = [
  { category: "Head/Neck", keywords: ["concussion", "head", "neck"] },
  { category: "Core", keywords: ["rib", "back", "abdomen", "oblique", "core"] },
  { category: "Upper Body", keywords: ["shoulder", "wrist", "hand", "thumb", "finger", "collarbone", "clavicle", "pectoral", "chest", "elbow", "bicep", "arm"] },
  { category: "Lower Body", keywords: ["ankle", "knee", "hamstring", "foot", "toe", "calf", "groin", "hip", "quad", "leg", "thigh", "heel", "shin", "acl", "mcl", "achilles", "fibula", "tibia"] },
  { category: "Unknown", keywords: ["undisclosed", "unknown", "illness"] },
];

export function categorizeInjury(label: string): string {
  const l = label.toLowerCase();
  for (const rule of INJURY_CATEGORY_RULES) {
    if (rule.keywords.some((k) => l.includes(k))) return rule.category;
  }
  return "Other";
}

const BODY_REGION_RULES: { region: string; keywords: string[] }[] = [
  { region: "Head/Neck", keywords: ["concussion", "head", "neck"] },
  { region: "Shoulder", keywords: ["shoulder", "collarbone", "clavicle", "sternoclav"] },
  { region: "Arm/Hand", keywords: ["elbow", "forearm", "wrist", "hand", "thumb", "finger", "bicep"] },
  { region: "Chest/Core", keywords: ["chest", "rib", "abdomen", "oblique", "back", "core", "sternum", "pectoral"] },
  { region: "Hip/Groin", keywords: ["hip", "groin"] },
  { region: "Hamstring", keywords: ["hamstring"] },
  { region: "Thigh/Quad", keywords: ["quad", "thigh"] },
  { region: "Knee", keywords: ["knee", "acl", "mcl", "patella"] },
  { region: "Lower Leg", keywords: ["calf", "shin", "fibula", "tibia", "lower leg", "achilles"] },
  { region: "Ankle/Foot", keywords: ["ankle", "foot", "toe", "heel"] },
];

export function bodyRegion(label: string): string {
  const l = label.toLowerCase();
  for (const rule of BODY_REGION_RULES) if (rule.keywords.some((k) => l.includes(k))) return rule.region;
  return "Other/Unknown";
}

/** Fixed head-to-toe row order for the heatmap. */
export const BODY_REGION_ORDER = ["Head/Neck", "Shoulder", "Arm/Hand", "Chest/Core", "Hip/Groin", "Hamstring", "Thigh/Quad", "Knee", "Lower Leg", "Ankle/Foot", "Other/Unknown"];

/** Standard-normal CDF (Abramowitz-Stegun), for the trend-slope p-value. */
export function normalCdf(z: number): number {
  const t = 1 / (1 + 0.2316419 * Math.abs(z));
  const d = 0.3989423 * Math.exp((-z * z) / 2);
  const p = d * t * (0.3193815 + t * (-0.3565638 + t * (1.781478 + t * (-1.821256 + t * 1.330274))));
  return z > 0 ? 1 - p : p;
}

/** Injury keys may be snake_cased ("foot_toe"); show them human-readable. */
export function formatInjury(injury: string): string {
  return injury.replace(/_/g, " ");
}

/* --------------------------------------------------------------- sorting */

export type SortDir = "asc" | "desc";
export interface SortState {
  key: string | null;
  dir: SortDir;
}

export function sortRows<T>(rows: T[], sort: SortState, accessors: Record<string, (r: T) => number | string>): T[] {
  if (!sort.key) return rows;
  const acc = accessors[sort.key];
  if (!acc) return rows;
  const copy = [...rows];
  copy.sort((a, b) => {
    const av = acc(a);
    const bv = acc(b);
    const cmp = typeof av === "number" && typeof bv === "number" ? av - bv : String(av).localeCompare(String(bv));
    return sort.dir === "asc" ? cmp : -cmp;
  });
  return copy;
}

/** First click on a column sorts descending (biggest first); re-click toggles. */
export function nextSort(prev: SortState, key: string): SortState {
  if (prev.key === key) return { key, dir: prev.dir === "asc" ? "desc" : "asc" };
  return { key, dir: "desc" };
}

/* --------------------------------------------------------------- filters */

export interface Filters {
  /** "All" or a season year as a string. */
  season: string;
  adp: [number, number];
  minGames: number;
}

export const DEFAULT_FILTERS: Filters = { season: "All", adp: [ADP_MIN, ADP_MAX], minGames: 1 };

export function parseFilters(raw: Partial<{ season: string; adpLo: number | string; adpHi: number | string; minGames: number | string }>): Filters {
  const season = raw.season && /^\d{4}$/.test(String(raw.season)) ? String(raw.season) : "All";
  const clamp = (v: unknown, lo: number, hi: number, d: number) => {
    const n = Number(v);
    return Number.isFinite(n) ? Math.max(lo, Math.min(hi, Math.round(n))) : d;
  };
  let adpLo = clamp(raw.adpLo, ADP_MIN, ADP_MAX, ADP_MIN);
  let adpHi = clamp(raw.adpHi, ADP_MIN, ADP_MAX, ADP_MAX);
  if (adpLo > adpHi) [adpLo, adpHi] = [adpHi, adpLo];
  return { season, adp: [adpLo, adpHi], minGames: clamp(raw.minGames, 1, 16, 1) };
}

export interface SeasonOption {
  year: number;
  hasData: boolean;
}

/** A contiguous range from the earliest to the latest season in the data. */
export function seasonOptions(data: InjuryImpactData | null): SeasonOption[] {
  const seasons = data?.meta.seasons ?? [];
  if (seasons.length === 0) return [];
  const withData = new Set(seasons);
  const min = Math.min(...seasons);
  const max = Math.max(...seasons);
  const opts: SeasonOption[] = [];
  for (let y = min; y <= max; y += 1) opts.push({ year: y, hasData: withData.has(y) });
  return opts;
}

export function filteredPlayers(data: InjuryImpactData, f: Filters): PlayerInjuryImpact[] {
  const [adpLo, adpHi] = f.adp;
  const fullAdpRange = adpLo === ADP_MIN && adpHi === ADP_MAX;
  return data.player_injury_impacts.filter((p) => {
    if (f.season !== "All" && p.season.toString() !== f.season) return false;
    if (p.overall_adp == null) {
      if (!fullAdpRange) return false;
    } else if (p.overall_adp < adpLo || p.overall_adp > adpHi) {
      return false;
    }
    if (p.games_missed < f.minGames) return false;
    return true;
  });
}

/** Drafted players per position within the selected season + ADP range. */
export function draftedByPosition(data: InjuryImpactData, f: Filters): Record<string, number> {
  const counts: Record<string, number> = {};
  const [adpLo, adpHi] = f.adp;
  const fullAdpRange = adpLo === ADP_MIN && adpHi === ADP_MAX;
  data.drafted_pool.forEach((r) => {
    if (f.season !== "All" && r.season.toString() !== f.season) return;
    if (r.overall_adp == null) {
      if (!fullAdpRange) return;
    } else if (r.overall_adp < adpLo || r.overall_adp > adpHi) {
      return;
    }
    counts[r.position] = (counts[r.position] || 0) + 1;
  });
  return counts;
}

/* ------------------------------------------------------- injury outcomes */

export interface OutcomeRow {
  position: string;
  exposure: number;
  episodes: number;
  injuryIncidence: number | null;
  timeLossIncidence: number | null;
  injuryBurden: number | null;
  fantasyBurden: number;
  per1k: Record<string, { inj: number; gm: number }>;
}

export interface InjuryOutcomes {
  rows: OutcomeRow[];
  total: OutcomeRow;
  hasExposure: boolean;
}

/**
 * Four formal, episode-based outcomes normalized by drafted player-seasons,
 * over the selected season + ADP range. Not gated by Min Games Missed.
 */
export function injuryOutcomes(data: InjuryImpactData, exposure: ExposureEntry[] | null, f: Filters): InjuryOutcomes {
  const [adpLo, adpHi] = f.adp;
  const fullAdpRange = adpLo === ADP_MIN && adpHi === ADP_MAX;
  const inRange = (adp: number | null) => (adp == null ? fullAdpRange : adp >= adpLo && adp <= adpHi);
  const inSeason = (s: number) => f.season === "All" || s.toString() === f.season;

  const exp: Record<string, number> = {};
  (data.drafted_pool ?? []).forEach((r) => {
    if (!inSeason(r.season) || !inRange(r.overall_adp)) return;
    exp[r.position] = (exp[r.position] || 0) + 1;
  });

  type Acc = { episodes: number; timeLoss: number; gamesMissed: number; fantasy: number };
  const acc: Record<string, Acc> = {};
  const blank = (): Acc => ({ episodes: 0, timeLoss: 0, gamesMissed: 0, fantasy: 0 });
  (data.player_injury_impacts ?? []).forEach((p) => {
    if (!inSeason(p.season) || !inRange(p.overall_adp)) return;
    const a = (acc[p.position] ??= blank());
    a.episodes += 1;
    if (p.games_missed > 0) a.timeLoss += 1;
    a.gamesMissed += p.games_missed;
    a.fantasy += p.net_value_lost;
  });

  const expMetrics: Record<string, Record<string, number>> = {};
  (exposure ?? []).forEach((e) => {
    if (!inSeason(e.season)) return;
    const m = (expMetrics[e.position] ??= {});
    (["snaps", "routes", "touches", "targets", "pass_attempts", "kickoff_returns"] as const).forEach((k) => {
      if (typeof e[k] === "number") m[k] = (m[k] || 0) + (e[k] as number);
    });
  });

  const RELEVANT: Record<string, string[]> = {
    QB: ["snaps", "routes", "pass_attempts"],
    RB: ["snaps", "routes", "touches", "targets"],
    WR: ["snaps", "routes", "touches", "targets"],
    TE: ["snaps", "routes", "touches", "targets"],
    All: ["snaps"],
  };

  const row = (pos: string, a: Acc, E: number): OutcomeRow => {
    const rates: Record<string, { inj: number; gm: number }> = {};
    const m = expMetrics[pos] || {};
    const ok = RELEVANT[pos] || [];
    Object.keys(m).forEach((k) => {
      if ((m[k] ?? 0) > 0 && ok.includes(k)) rates[k] = { inj: (a.episodes / (m[k] as number)) * 1000, gm: (a.gamesMissed / (m[k] as number)) * 1000 };
    });
    return {
      position: pos,
      exposure: E,
      episodes: a.episodes,
      injuryIncidence: E > 0 ? a.episodes / E : null,
      timeLossIncidence: E > 0 ? a.timeLoss / E : null,
      injuryBurden: E > 0 ? a.gamesMissed / E : null,
      fantasyBurden: a.fantasy,
      per1k: rates,
    };
  };

  const rows = POS4.filter((pos) => acc[pos] || exp[pos]).map((pos) => row(pos, acc[pos] || blank(), exp[pos] || 0));
  const totalAcc = POS4.reduce<Acc>((s, pos) => {
    const a = acc[pos] || blank();
    return { episodes: s.episodes + a.episodes, timeLoss: s.timeLoss + a.timeLoss, gamesMissed: s.gamesMissed + a.gamesMissed, fantasy: s.fantasy + a.fantasy };
  }, blank());
  const totalExp = POS4.reduce((s, pos) => s + (exp[pos] || 0), 0);
  const hasExposure = rows.some((r) => Object.keys(r.per1k).length > 0);
  return { rows, total: row("All", totalAcc, totalExp), hasExposure };
}

/* -------------------------------------------------- draft-capital risk */

export interface RiskRow {
  pos: string;
  bucket: string;
  round: string;
  lo: number;
  hi: number;
  drafted: number;
  injured: number;
  pMiss1: number | null;
  pMiss2: number | null;
  pMiss4: number | null;
  pMiss8: number | null;
  eGames: number | null;
  ePts: number | null;
  eVorpLost: number | null;
  pBelow: number | null;
  pKiller: number | null;
  draftCostVorp: number;
  injAdjVorp: number;
  fragility: number | null;
  exploratory: boolean;
}

export interface DraftCapitalRisk {
  rows: RiskRow[];
  frontier: RiskRow[];
  mostFragile: RiskRow | null;
  bestValue: RiskRow | null;
  topKiller: RiskRow | null;
  minDisplay: number;
  minTakeaway: number;
}

/** Probability + expected-value outcomes per position x ADP bucket. Honors the season filter only. */
export function draftCapitalRisk(data: InjuryImpactData, season: string): DraftCapitalRisk {
  const inSeason = (s: number) => season === "All" || s.toString() === season;

  const groups = new Map<string, PlayerInjuryImpact[]>();
  (data.player_injury_impacts ?? []).forEach((p) => {
    if (!inSeason(p.season) || p.overall_adp == null) return;
    const key = `${p.player}|${p.season}`;
    const arr = groups.get(key);
    if (arr) arr.push(p);
    else groups.set(key, [p]);
  });
  type PS = { pos: string; adp: number; gm: number; regGm: number; epl: number; expected: number; actual: number; replacement: number };
  const playerSeasons: PS[] = [];
  groups.forEach((rows) => {
    const primary = rows.reduce((a, b) => (b.games_missed > a.games_missed ? b : a));
    playerSeasons.push({
      pos: primary.position,
      adp: Math.min(...rows.map((r) => r.overall_adp as number)),
      gm: rows.reduce((s, r) => s + r.games_missed, 0),
      regGm: rows.reduce((s, r) => s + regGm(r), 0),
      epl: rows.reduce((s, r) => s + r.estimated_points_lost, 0),
      expected: primary.expected_fantasy_points,
      actual: primary.actual_fantasy_points,
      replacement: primary.replacement_level_points,
    });
  });

  const draftedCount = (pos: string, lo: number, hi: number) =>
    (data.drafted_pool ?? []).filter((r) => r.position === pos && inSeason(r.season) && r.overall_adp != null && r.overall_adp >= lo && r.overall_adp <= hi).length;

  const rows: RiskRow[] = POS4.flatMap((pos) =>
    ADP_BUCKETS.map((b) => {
      const D = draftedCount(pos, b.lo, b.hi);
      const I = playerSeasons.filter((ps) => ps.pos === pos && ps.adp >= b.lo && ps.adp <= b.hi);
      const n = I.length;
      const geq = (k: number) => I.filter((ps) => ps.gm >= k).length;
      const sumGM = I.reduce((s, x) => s + x.gm, 0);
      const sumEPL = I.reduce((s, x) => s + x.epl, 0);
      const sumVorpLost = I.reduce((s, x) => s + (Math.max(0, x.expected - x.replacement) * x.regGm) / GAMES_PER_SEASON, 0);
      const belowRepl = I.filter((x) => x.actual < x.replacement).length;
      const killers = I.filter((x) => x.regGm >= 8 && x.actual < x.replacement && x.expected - x.replacement >= SEASON_KILLER_MIN_VORP).length;
      const draftCostVorp = n > 0 ? I.reduce((s, x) => s + Math.max(0, x.expected - x.replacement), 0) / n : 0;
      const eVorpLost = D > 0 ? sumVorpLost / D : null;
      const fragility = draftCostVorp > 1 && eVorpLost != null ? eVorpLost / draftCostVorp : null;
      return {
        pos,
        bucket: b.label,
        round: b.round,
        lo: b.lo,
        hi: b.hi,
        drafted: D,
        injured: n,
        pMiss1: D > 0 ? geq(1) / D : null,
        pMiss2: D > 0 ? geq(2) / D : null,
        pMiss4: D > 0 ? geq(4) / D : null,
        pMiss8: D > 0 ? geq(8) / D : null,
        eGames: D > 0 ? sumGM / D : null,
        ePts: D > 0 ? sumEPL / D : null,
        eVorpLost,
        pBelow: D > 0 ? belowRepl / D : null,
        pKiller: D > 0 ? killers / D : null,
        draftCostVorp,
        injAdjVorp: eVorpLost != null ? draftCostVorp - eVorpLost : draftCostVorp,
        fragility,
        exploratory: D > 0 && D < DRAFT_RISK_MIN_DISPLAY,
      };
    }),
  ).filter((r) => r.drafted > 0 || r.injured > 0);

  const frontier = rows.filter((r) => r.drafted >= DRAFT_RISK_MIN_DISPLAY && r.draftCostVorp > 1);
  const strong = rows.filter((r) => r.drafted >= DRAFT_RISK_MIN_TAKEAWAY);
  const withFrag = strong.filter((r) => r.fragility != null);
  const mostFragile = withFrag.length ? withFrag.reduce((a, b) => ((b.fragility as number) > (a.fragility as number) ? b : a)) : null;
  const strongFrontier = frontier.filter((r) => r.drafted >= DRAFT_RISK_MIN_TAKEAWAY);
  const bestValue = strongFrontier.length ? strongFrontier.reduce((a, b) => (b.injAdjVorp > a.injAdjVorp ? b : a)) : null;
  const scored = strong.filter((r) => r.pKiller != null);
  const topKiller = scored.length ? scored.reduce((a, b) => ((b.pKiller as number) > (a.pKiller as number) ? b : a)) : null;

  return { rows, frontier, mostFragile, bestValue, topKiller, minDisplay: DRAFT_RISK_MIN_DISPLAY, minTakeaway: DRAFT_RISK_MIN_TAKEAWAY };
}

/* ------------------------------------------------ injury predictability */

export interface KmRow {
  week: number;
  [key: string]: number | null;
}

export interface SeverityRow {
  label: string;
  n: number;
  meanGm: number;
  p8: number;
  pEnd: number;
  severe: number;
}

export interface MatrixCell {
  rr: number | null;
  n: number;
  denom: number;
}

export interface InjuryPredictability {
  km: KmRow[];
  kmEnd: Record<string, number | null>;
  cohort: Record<string, number>;
  severityByPrior: SeverityRow[];
  matrix: { regions: string[]; cells: Record<string, Record<string, MatrixCell>>; maxAbsLog: number };
  sameByGap: { gap: number; n: number; samePct: number }[];
  sameByPos: { pos: string; n: number; samePct: number }[];
  obsSame: number;
  expSamePct: number;
  sameLift: number | null;
  transitions: number;
  callouts: string[];
  calloutSummary: string;
}

/** The fmtX helper the callouts use: "1.23×". */
const fmtX = (v: number | null | undefined) => (v == null ? "n/a" : `${v.toFixed(2)}×`);

/** Prior-history predictability: KM survival, severity by prior, the recurrence matrix. All seasons. */
export function injuryPredictability(data: InjuryImpactData): InjuryPredictability {
  const POS = POS4;
  const P = data.player_injury_impacts ?? [];
  const POOL = data.drafted_pool ?? [];

  const cohort: Record<string, number> = { All: 0 };
  const evWk: Record<string, number[]> = { All: Array(19).fill(0) as number[] };
  POS.forEach((p) => {
    evWk[p] = Array(19).fill(0) as number[];
  });
  POOL.forEach((r) => {
    if (r.overall_adp != null && evWk[r.position]) {
      cohort["All"] = (cohort["All"] ?? 0) + 1;
      cohort[r.position] = (cohort[r.position] || 0) + 1;
    }
  });
  P.forEach((p) => {
    if (p.overall_adp == null || !evWk[p.position] || p.week_of_injury < 1) return;
    const w = Math.min(p.week_of_injury, 18);
    (evWk[p.position] as number[])[w] = ((evWk[p.position] as number[])[w] ?? 0) + 1;
    (evWk["All"] as number[])[w] = ((evWk["All"] as number[])[w] ?? 0) + 1;
  });
  const keys = ["All", ...POS];
  const cum: Record<string, number> = {};
  keys.forEach((k) => (cum[k] = 0));
  const km: KmRow[] = [{ week: 0, All: 100, QB: 100, RB: 100, WR: 100, TE: 100 }];
  for (let w = 1; w <= 17; w += 1) {
    const row: KmRow = { week: w };
    keys.forEach((k) => {
      cum[k] = (cum[k] ?? 0) + ((evWk[k] as number[])[w] || 0);
      const Nk = cohort[k] || 0;
      row[k] = Nk > 0 ? Math.round((1 - (cum[k] as number) / Nk) * 1000) / 10 : null;
    });
    km.push(row);
  }
  const kmEnd: Record<string, number | null> = {};
  keys.forEach((k) => (kmEnd[k] = (cohort[k] ?? 0) > 0 ? Math.round((1 - (cum[k] as number) / (cohort[k] as number)) * 1000) / 10 : null));

  const byId: Record<string, PlayerInjuryImpact[]> = {};
  P.forEach((p) => {
    if (p.gsis_id) (byId[p.gsis_id] ??= []).push(p);
  });
  const primary: Record<string, Record<number, { reg: string; gm: number; pos: string }>> = {};
  P.forEach((p) => {
    if (!p.gsis_id) return;
    const m = (primary[p.gsis_id] ??= {});
    const cur = m[p.season];
    if (!cur || p.games_missed > cur.gm) m[p.season] = { reg: bodyRegion(p.injury), gm: p.games_missed, pos: p.position };
  });

  const priorSeasons = (p: PlayerInjuryImpact) => (p.gsis_id ? new Set((byId[p.gsis_id] ?? []).filter((x) => x.season < p.season).map((x) => x.season)).size : 0);
  const sevBuckets: { rows: PlayerInjuryImpact[]; label: string }[] = [
    { label: "First recorded injury", rows: [] },
    { label: "1 prior injured season", rows: [] },
    { label: "2+ prior injured seasons", rows: [] },
  ];
  P.filter((p) => p.gsis_id).forEach((p) => {
    const c = priorSeasons(p);
    (sevBuckets[c === 0 ? 0 : c === 1 ? 1 : 2] as { rows: PlayerInjuryImpact[] }).rows.push(p);
  });
  const severityByPrior: SeverityRow[] = sevBuckets.map((b) => {
    const n = b.rows.length;
    const mean = (fn: (x: PlayerInjuryImpact) => number) => (n ? b.rows.reduce((s, x) => s + fn(x), 0) / n : 0);
    const share = (fn: (x: PlayerInjuryImpact) => boolean) => (n ? (100 * b.rows.filter(fn).length) / n : 0);
    return {
      label: b.label,
      n,
      meanGm: mean((x) => x.games_missed),
      p8: share((x) => x.games_missed >= 8),
      pEnd: share((x) => x.season_ending),
      severe: share((x) => x.impact_label === "Severe"),
    };
  });

  type Tr = { prev: string; next: string; gap: number; pos: string };
  const T: Tr[] = [];
  Object.values(primary).forEach((seas) => {
    const ys = Object.keys(seas)
      .map(Number)
      .sort((a, b) => a - b);
    for (let i = 0; i < ys.length - 1; i += 1) {
      const y0 = ys[i] as number;
      const y1 = ys[i + 1] as number;
      const gap = y1 - y0;
      const a = seas[y0];
      const b = seas[y1];
      if (gap <= 3 && a && b) T.push({ prev: a.reg, next: b.reg, gap, pos: a.pos });
    }
  });
  const N = T.length;
  const REGIONS = BODY_REGION_ORDER.filter((r) => T.some((t) => t.prev === r || t.next === r));
  const MIN_DENOM = 20;
  const MIN_CELL = 3;
  const rrOf = (A: string, B: string): MatrixCell => {
    const pa = T.filter((t) => t.prev === A);
    const na = T.filter((t) => t.prev !== A);
    const nAB = pa.filter((t) => t.next === B).length;
    if (pa.length < MIN_DENOM || nAB < MIN_CELL) return { rr: null, n: nAB, denom: pa.length };
    const pB_nA = na.filter((t) => t.next === B).length / na.length;
    return { rr: pB_nA > 0 ? nAB / pa.length / pB_nA : null, n: nAB, denom: pa.length };
  };
  const cells: Record<string, Record<string, MatrixCell>> = {};
  let maxAbsLog = Math.log(1.5);
  REGIONS.forEach((A) => {
    cells[A] = {};
    REGIONS.forEach((B) => {
      const c = rrOf(A, B);
      (cells[A] as Record<string, MatrixCell>)[B] = c;
      if (c.rr && c.rr > 0) maxAbsLog = Math.max(maxAbsLog, Math.abs(Math.log(c.rr)));
    });
  });

  const nextDist: Record<string, number> = {};
  const prevDist: Record<string, number> = {};
  T.forEach((t) => {
    nextDist[t.next] = (nextDist[t.next] || 0) + 1;
    prevDist[t.prev] = (prevDist[t.prev] || 0) + 1;
  });
  const expSame = REGIONS.reduce((s, r) => s + ((prevDist[r] || 0) / N) * ((nextDist[r] || 0) / N), 0);
  const sameByGap = [1, 2, 3].map((g) => {
    const tg = T.filter((t) => t.gap === g);
    const same = tg.filter((t) => t.prev === t.next).length;
    return { gap: g, n: tg.length, samePct: tg.length ? (100 * same) / tg.length : 0 };
  });
  const sameByPos = POS.map((pos) => {
    const tp = T.filter((t) => t.pos === pos);
    const same = tp.filter((t) => t.prev === t.next).length;
    return { pos, n: tp.length, samePct: tp.length ? (100 * same) / tp.length : 0 };
  });
  const obsSame = N ? (100 * T.filter((t) => t.prev === t.next).length) / N : 0;
  const sameLift = expSame > 0 ? obsSame / 100 / expSame : null;

  const ham = cells["Hamstring"]?.["Hamstring"];
  const knee = cells["Knee"]?.["Knee"];
  const head = cells["Head/Neck"]?.["Head/Neck"];
  const kneeHam = cells["Knee"]?.["Hamstring"];
  const kneeAnk = cells["Knee"]?.["Ankle/Foot"];
  const callouts: string[] = [];
  if (ham?.rr != null) callouts.push(`**Hamstring recurrence is real but moderate.** A prior hamstring injury makes the next injury **${fmtX(ham.rr)} more likely** to be another hamstring.`);
  if (knee?.rr != null) callouts.push(`**Knee injuries are especially sticky.** Prior knee injuries raise same-region recurrence to **${fmtX(knee.rr)} baseline**.`);
  if (head?.rr != null) callouts.push(`**Head/neck shows the strongest recurrence.** Prior concussion or head/neck injury raises same-region risk to **${fmtX(head.rr)} baseline**.`);
  if (kneeHam?.rr != null || kneeAnk?.rr != null) callouts.push(`**The risk stays local.** Prior knee injuries do not meaningfully increase future hamstring or ankle/foot injuries.`);
  callouts.push(
    `**One healthy year does not reset the risk.** Same-region recurrence is about **${(sameByGap[0] as { samePct: number }).samePct.toFixed(0)}%** the next season and **${(sameByGap[1] as { samePct: number }).samePct.toFixed(0)}%** two seasons later.`,
  );
  const calloutSummary = `Overall, the next injury occurs in the same body region **${obsSame.toFixed(0)}% of the time${sameLift ? `, ${sameLift.toFixed(2)}× above baseline` : ""}**. Injury history is most useful when it is **body-part specific**, not as a blanket "injury-prone" label.`;

  return {
    km,
    kmEnd,
    cohort,
    severityByPrior,
    matrix: { regions: REGIONS, cells, maxAbsLog },
    sameByGap,
    sameByPos,
    obsSame,
    expSamePct: expSame * 100,
    sameLift,
    transitions: N,
    callouts,
    calloutSummary,
  };
}

/* ---------------------------------------------------- aging and workload */

export interface KmStat {
  N: number;
  weekly: Record<number, number>;
  end: number | null;
  injPct: number;
  meanGm: number;
  p8: number;
}

export interface GroupStat {
  n: number;
  injPct: number;
  meanGm: number;
  p8: number;
}

export interface AgingWorkload {
  ageKm: KmRow[];
  ageSeverity: { bucket: AgeBucket; n: number; injPct: number; end: number | null; meanGm: number; p8: number }[];
  workloadKm: KmRow[];
  workloadStats: { tier: WorkloadTier; n: number; injPct: number; end: number | null; meanGm: number; p8: number }[];
  workloadSignal: { diff: number; p: number; significant: boolean };
  priorClean: { dataStart: number; coveredPct: number; noPrior: GroupStat; prior: GroupStat };
  eligibleN: number;
  totalN: number;
  callouts: string[];
}

export function ageBucket(a: number): AgeBucket {
  return a <= 24 ? "≤24" : a <= 27 ? "25-27" : a <= 30 ? "28-30" : "31+";
}

/** Age and prior-workload strata from the nflverse-matched panel. Null without the panel. */
export function agingWorkload(panel: PanelRow[] | null): AgingWorkload | null {
  if (!panel || panel.length === 0) return null;

  const km = (rows: PanelRow[]): KmStat => {
    const N = rows.length;
    const ev = Array(19).fill(0) as number[];
    rows.forEach((r) => {
      if (r.episodes > 0 && r.first_week >= 1) ev[Math.min(r.first_week, 18)] = (ev[Math.min(r.first_week, 18)] ?? 0) + 1;
    });
    const weekly: Record<number, number> = {};
    let cum = 0;
    for (let w = 1; w <= 17; w += 1) {
      cum += ev[w] ?? 0;
      weekly[w] = N > 0 ? Math.round((1 - cum / N) * 1000) / 10 : 100;
    }
    const injured = rows.filter((r) => r.episodes > 0);
    return {
      N,
      weekly,
      end: N > 0 ? Math.round((1 - cum / N) * 1000) / 10 : null,
      injPct: N > 0 ? Math.round((injured.length / N) * 1000) / 10 : 0,
      meanGm: injured.length ? injured.reduce((s, r) => s + r.games_missed, 0) / injured.length : 0,
      p8: injured.length ? (100 * injured.filter((r) => r.games_missed >= 8).length) / injured.length : 0,
    };
  };
  const merge = (keys: readonly string[], weeklyOf: (k: string) => Record<number, number>): KmRow[] => {
    const arr: KmRow[] = [{ week: 0, ...Object.fromEntries(keys.map((k) => [k, 100])) }];
    for (let w = 1; w <= 17; w += 1) {
      const row: KmRow = { week: w };
      keys.forEach((k) => (row[k] = weeklyOf(k)[w] ?? null));
      arr.push(row);
    }
    return arr;
  };

  const ageGroups: Record<string, PanelRow[]> = {};
  AGE_BUCKETS.forEach((b) => (ageGroups[b] = []));
  panel.forEach((r) => (ageGroups[ageBucket(r.age)] as PanelRow[]).push(r));
  const ageStat: Record<string, KmStat> = {};
  AGE_BUCKETS.forEach((b) => (ageStat[b] = km(ageGroups[b] as PanelRow[])));
  const ageKm = merge(AGE_BUCKETS, (b) => (ageStat[b] as KmStat).weekly);
  const ageSeverity = AGE_BUCKETS.map((b) => {
    const s = ageStat[b] as KmStat;
    return { bucket: b, n: (ageGroups[b] as PanelRow[]).filter((r) => r.episodes > 0).length, injPct: s.injPct, end: s.end, meanGm: s.meanGm, p8: s.p8 };
  });

  const eligible = panel.filter((r) => r.prev_snaps >= 0);
  const byPos: Record<string, PanelRow[]> = {};
  eligible.forEach((r) => (byPos[r.position] ??= []).push(r));
  const tierOf = new Map<PanelRow, WorkloadTier>();
  Object.values(byPos).forEach((arr) => {
    const sorted = [...arr].sort((a, b) => a.prev_snaps - b.prev_snaps);
    const n = sorted.length;
    sorted.forEach((r, i) => tierOf.set(r, i < n / 3 ? "Light" : i < (2 * n) / 3 ? "Moderate" : "Heavy"));
  });
  const wlGroups: Record<WorkloadTier, PanelRow[]> = { Light: [], Moderate: [], Heavy: [] };
  eligible.forEach((r) => wlGroups[tierOf.get(r) as WorkloadTier].push(r));
  const wlStat: Record<string, KmStat> = {};
  WORKLOAD_TIERS.forEach((t) => (wlStat[t] = km(wlGroups[t])));
  const workloadKm = merge(WORKLOAD_TIERS, (t) => (wlStat[t] as KmStat).weekly);
  const workloadStats = WORKLOAD_TIERS.map((t) => {
    const s = wlStat[t] as KmStat;
    return { tier: t, n: wlGroups[t].length, injPct: s.injPct, end: s.end, meanGm: s.meanGm, p8: s.p8 };
  });

  const dataStart = panel.reduce((m, r) => Math.min(m, r.season), Infinity);
  const grp = (rows: PanelRow[]): GroupStat => {
    const inj = rows.filter((r) => r.episodes > 0);
    return {
      n: rows.length,
      injPct: rows.length ? (100 * inj.length) / rows.length : 0,
      meanGm: inj.length ? inj.reduce((s, r) => s + r.games_missed, 0) / inj.length : 0,
      p8: inj.length ? (100 * inj.filter((r) => r.games_missed >= 8).length) / inj.length : 0,
    };
  };
  const observed = panel.filter((r) => r.rookie_year >= dataStart);
  const priorClean = {
    dataStart,
    coveredPct: Math.round((observed.length / panel.length) * 100),
    noPrior: grp(observed.filter((r) => r.prior_inj === 0)),
    prior: grp(observed.filter((r) => r.prior_inj >= 1)),
  };

  const pct = (v: number | null) => (v == null ? "-" : `${v.toFixed(0)}%`);
  const light = workloadStats[0] as (typeof workloadStats)[number];
  const heavy = workloadStats[2] as (typeof workloadStats)[number];
  const workloadSignal = (() => {
    const p1 = heavy.injPct / 100;
    const p2 = light.injPct / 100;
    const n1 = heavy.n;
    const n2 = light.n;
    const pool = (p1 * n1 + p2 * n2) / (n1 + n2 || 1);
    const se = Math.sqrt(pool * (1 - pool) * (1 / (n1 || 1) + 1 / (n2 || 1)));
    const z = se > 0 ? (p1 - p2) / se : 0;
    const p = 2 * (1 - normalCdf(Math.abs(z)));
    return { diff: (p1 - p2) * 100, p, significant: p < 0.05 && p1 > p2 };
  })();
  const callouts = [
    `**Age has little effect on injury odds.** Players ≤24 were injured ${pct((ageStat["≤24"] as KmStat).injPct)} of the time vs ${pct((ageStat["31+"] as KmStat).injPct)} for players 31+, though older players missed slightly more time once hurt.`,
    workloadSignal.significant
      ? `**Heavy prior workload raises injury risk.** Heavy-workload players were injured **${pct(heavy.injPct)}** of the time vs **${pct(light.injPct)}** for light workloads (p ≈ ${workloadSignal.p.toFixed(2)}).`
      : `**Prior workload adds little signal.** Heavy-workload players were injured **${pct(heavy.injPct)}** of the time vs **${pct(light.injPct)}** for light workloads (p ≈ ${workloadSignal.p.toFixed(2)}).`,
    `**Prior injury raises future risk only modestly.** Players with a prior injury were hurt **${pct(priorClean.prior.injPct)} vs ${pct(priorClean.noPrior.injPct)}**, with little difference in severity.`,
  ];

  return { ageKm, ageSeverity, workloadKm, workloadStats, workloadSignal, priorClean, eligibleN: eligible.length, totalN: panel.length, callouts };
}

/* ---------------------------------------------------------- injury timing */

export interface TimingRow {
  pos: string;
  drafted: number;
  injuries: number;
  playoffMissRate: number | null;
  pctHitPlayoffs: number;
  avgRemPct: number;
}

export interface InjuryTiming {
  byPos: TimingRow[];
  phase: { early: number; mid: number; late: number };
  totalInj: number;
  worstPlayoff: TimingRow | null;
}

/** When injuries strike and how much of the season they cost. All seasons. */
export function injuryTiming(data: InjuryImpactData): InjuryTiming {
  const POS: string[] = [...POS4];
  const drafted: Record<string, number> = {};
  (data.drafted_pool ?? []).forEach((r) => {
    if (POS.includes(r.position)) drafted[r.position] = (drafted[r.position] || 0) + 1;
  });
  type A = { inj: number; playoffPlayers: Set<string>; hitPlayoff: number; remSum: number };
  const acc: Record<string, A> = {};
  POS.forEach((p) => (acc[p] = { inj: 0, playoffPlayers: new Set(), hitPlayoff: 0, remSum: 0 }));
  const phase = { early: 0, mid: 0, late: 0 };
  (data.player_injury_impacts ?? []).forEach((p) => {
    const a = acc[p.position];
    if (!a) return;
    const W = p.week_of_injury || 0;
    if (W < 1) return;
    if (p.reg_games_missed === 0 && (p.playoff_games_missed ?? 0) > 0) return;
    const G = regGm(p) || 0;
    const missEnd = Math.min(W + G - 1, 17);
    a.inj += 1;
    if (missEnd >= 15) {
      a.hitPlayoff += 1;
      a.playoffPlayers.add(`${p.player}|${p.season}`);
    }
    a.remSum += G / Math.max(1, 17 - W + 1);
    if (W <= 6) phase.early += 1;
    else if (W <= 13) phase.mid += 1;
    else phase.late += 1;
  });
  const byPos: TimingRow[] = POS.filter((p) => (acc[p] as A).inj > 0).map((p) => {
    const a = acc[p] as A;
    const D = drafted[p] || 0;
    return {
      pos: p,
      drafted: D,
      injuries: a.inj,
      playoffMissRate: D ? (a.playoffPlayers.size / D) * 100 : null,
      pctHitPlayoffs: a.inj ? (a.hitPlayoff / a.inj) * 100 : 0,
      avgRemPct: a.inj ? (a.remSum / a.inj) * 100 : 0,
    };
  });
  const totalInj = phase.early + phase.mid + phase.late;
  const worstPlayoff = byPos.reduce<TimingRow | null>((b, r) => (r.playoffMissRate != null && (b == null || r.playoffMissRate > (b.playoffMissRate ?? 0)) ? r : b), null);
  return { byPos, phase, totalInj, worstPlayoff };
}

/* --------------------------------------------------- injury type classes */

export interface TypeRiskRow {
  type: string;
  n: number;
  medGM: number;
  p8: number;
  vorpEp: number;
  ret: number | null;
  rein8: number | null;
  topPos: string;
  cls: string;
  tags: string[];
}

export interface InjuryTypeRisk {
  rows: TypeRiskRow[];
  hasRecovery: boolean;
}

/** Frequency x damage classification, with recurrence and recovery overlays. */
export function injuryTypeRisk(data: InjuryImpactData, postReturn: PostReturnData | null): InjuryTypeRisk {
  const prByType: Record<string, PostReturnGroup> = {};
  (postReturn?.byType ?? []).forEach((r) => {
    if (r.key) prByType[r.key] = r;
  });
  const g: Record<string, { n: number; gm: number[]; p8: number; vorp: number; pos: Record<string, number> }> = {};
  (data.player_injury_impacts ?? []).forEach((p) => {
    const t = cleanInjuryLabel(p.injury);
    if (/undisclosed|unknown/i.test(t)) return;
    const x = (g[t] ??= { n: 0, gm: [], p8: 0, vorp: 0, pos: {} });
    x.n += 1;
    x.gm.push(p.games_missed);
    if (p.games_missed >= 8) x.p8 += 1;
    x.vorp += p.net_value_lost;
    x.pos[p.position] = (x.pos[p.position] || 0) + 1;
  });
  const median = (a: number[]) => {
    if (!a.length) return 0;
    const s = [...a].sort((x, y) => x - y);
    const m = s.length >> 1;
    return s.length % 2 ? (s[m] as number) : ((s[m - 1] as number) + (s[m] as number)) / 2;
  };
  const MIN = 30;
  const rows: TypeRiskRow[] = Object.entries(g)
    .filter(([, x]) => x.n >= MIN)
    .map(([type, x]) => {
      const pr = prByType[type];
      const p8 = (100 * x.p8) / x.n;
      const vorpEp = x.vorp / x.n;
      const ret = pr?.median_return_ratio ?? null;
      const rein8 = pr?.reinjury_8wk ?? null;
      const frequent = x.n >= 100;
      const damaging = p8 >= 22;
      const recurrent = rein8 != null && rein8 >= 22;
      const lingering = ret != null && ret <= 0.8;
      const cls = frequent ? (damaging ? "Frequent & damaging" : "Frequent & manageable") : damaging ? "Rare but catastrophic" : "Situational";
      const tags: string[] = [];
      if (recurrent) tags.push("High recurrence");
      if (lingering) tags.push("Lingering return");
      const topPos = (Object.entries(x.pos).sort((a, b) => b[1] - a[1])[0] as [string, number])[0];
      return { type, n: x.n, medGM: median(x.gm), p8: Math.round(p8), vorpEp: Math.round(vorpEp), ret, rein8, topPos, cls, tags };
    })
    .sort((a, b) => TYPE_CLASS_ORDER.indexOf(a.cls) - TYPE_CLASS_ORDER.indexOf(b.cls) || b.n - a.n);
  return { rows, hasRecovery: !!postReturn };
}

/* ---------------------------------------------------------- season trends */

export interface TrendPoint {
  season: string;
  drafted: number;
  injured: number;
  episodes: number;
  snaps: number;
  rawPct: number;
  stdPct: number;
  ci: [number, number];
  burdenRaw: number;
  burdenStd: number;
  rawRate: number;
  stdRate: number;
  ciRate: [number, number];
  burdenRawSnap: number;
  burdenStdSnap: number;
  partial: boolean;
}

export interface TrendFit {
  annualPct: number;
  totalPct: number;
  p: number;
  firstYear: number;
  lastYear: number;
}

export interface SeasonTrends {
  points: TrendPoint[];
  fit: TrendFit | null;
  partialSeasons: string[];
  hasSnaps: boolean;
}

/** "Are injuries becoming less common?": every season, position-standardized, honoring the ADP range. */
export function seasonTrends(data: InjuryImpactData, exposure: ExposureEntry[] | null, adpRange: [number, number]): SeasonTrends | null {
  if (!data.drafted_pool) return null;
  const [adpLo, adpHi] = adpRange;
  const fullAdp = adpLo === ADP_MIN && adpHi === ADP_MAX;
  const inRange = (adp: number | null) => (adp == null ? fullAdp : adp >= adpLo && adp <= adpHi);

  const drafted: Record<number, Record<string, number>> = {};
  data.drafted_pool.forEach((r) => {
    if (!inRange(r.overall_adp)) return;
    (drafted[r.season] ??= {})[r.position] = ((drafted[r.season] ??= {})[r.position] || 0) + 1;
  });
  const injuredSet: Record<number, Record<string, Set<string>>> = {};
  const episodes: Record<number, Record<string, number>> = {};
  const gm: Record<number, Record<string, number>> = {};
  data.player_injury_impacts.forEach((p) => {
    if (!inRange(p.overall_adp) || regGm(p) <= 0) return;
    ((injuredSet[p.season] ??= {})[p.position] ??= new Set()).add(p.player);
    (episodes[p.season] ??= {})[p.position] = ((episodes[p.season] ??= {})[p.position] || 0) + 1;
    (gm[p.season] ??= {})[p.position] = ((gm[p.season] ??= {})[p.position] || 0) + regGm(p);
  });

  const snaps: Record<number, Record<string, number>> = {};
  (exposure ?? []).forEach((e) => {
    const sn = e.reg_snaps ?? e.snaps;
    if (typeof sn === "number") (snaps[e.season] ??= {})[e.position] = ((snaps[e.season] ??= {})[e.position] || 0) + sn;
  });
  const hasSnaps = fullAdp && (exposure ?? []).some((e) => (e.reg_snaps ?? e.snaps ?? 0) > 0);

  const totalByPos: Record<string, number> = {};
  let grandTotal = 0;
  Object.values(drafted).forEach((bp) =>
    POS4.forEach((pos) => {
      totalByPos[pos] = (totalByPos[pos] || 0) + (bp[pos] || 0);
      grandTotal += bp[pos] || 0;
    }),
  );
  const weight: Record<string, number> = {};
  POS4.forEach((pos) => {
    weight[pos] = grandTotal > 0 ? (totalByPos[pos] || 0) / grandTotal : 0;
  });
  const snapByPos: Record<string, number> = {};
  let grandSnaps = 0;
  Object.values(snaps).forEach((bp) =>
    POS4.forEach((pos) => {
      snapByPos[pos] = (snapByPos[pos] || 0) + (bp[pos] || 0);
      grandSnaps += bp[pos] || 0;
    }),
  );
  const wSnap: Record<string, number> = {};
  POS4.forEach((pos) => {
    wSnap[pos] = grandSnaps > 0 ? (snapByPos[pos] || 0) / grandSnaps : 0;
  });

  const seasons = Object.keys(drafted)
    .map(Number)
    .sort((a, b) => a - b);
  const points: TrendPoint[] = seasons.map((s) => {
    let totDraft = 0;
    let totInj = 0;
    let totGm = 0;
    let totEp = 0;
    let totSnap = 0;
    let stdInj = 0;
    let stdBurden = 0;
    let varStd = 0;
    let stdRate = 0;
    let stdBurdenSnap = 0;
    let varRate = 0;
    POS4.forEach((pos) => {
      const n = drafted[s]?.[pos] || 0;
      const inj = injuredSet[s]?.[pos]?.size || 0;
      const ep = episodes[s]?.[pos] || 0;
      const g = gm[s]?.[pos] || 0;
      const snp = snaps[s]?.[pos] || 0;
      totDraft += n;
      totInj += inj;
      totGm += g;
      totEp += ep;
      totSnap += snp;
      if (n > 0) {
        const p = inj / n;
        stdInj += (weight[pos] as number) * p;
        stdBurden += (weight[pos] as number) * (g / n);
        varStd += ((weight[pos] as number) * (weight[pos] as number) * (p * (1 - p))) / n;
      }
      if (snp > 0) {
        stdRate += (wSnap[pos] as number) * (ep / snp) * 1000;
        stdBurdenSnap += (wSnap[pos] as number) * (g / snp) * 1000;
        varRate += ((wSnap[pos] as number) * (wSnap[pos] as number) * ep) / (snp * snp) * 1e6;
      }
    });
    const rawPct = totDraft > 0 ? (totInj / totDraft) * 100 : 0;
    const stdPct = stdInj * 100;
    const se = Math.sqrt(varStd) * 100;
    const rawRate = totSnap > 0 ? (totEp / totSnap) * 1000 : 0;
    const seRate = Math.sqrt(varRate);
    const r1 = (v: number) => Math.round(v * 100) / 100;
    return {
      season: s.toString(),
      drafted: totDraft,
      injured: totInj,
      episodes: totEp,
      snaps: totSnap,
      rawPct: Math.round(rawPct * 10) / 10,
      stdPct: Math.round(stdPct * 10) / 10,
      ci: [Math.round((stdPct - 1.96 * se) * 10) / 10, Math.round((stdPct + 1.96 * se) * 10) / 10] as [number, number],
      burdenRaw: totDraft > 0 ? r1(totGm / totDraft) : 0,
      burdenStd: r1(stdBurden),
      rawRate: r1(rawRate),
      stdRate: r1(stdRate),
      ciRate: [r1(stdRate - 1.96 * seRate), r1(stdRate + 1.96 * seRate)] as [number, number],
      burdenRawSnap: totSnap > 0 ? r1((totGm / totSnap) * 1000) : 0,
      burdenStdSnap: r1(stdBurdenSnap),
      partial: false,
    };
  });

  const median = (xs: number[]) => {
    const s = xs.filter((v) => v > 0).sort((a, b) => a - b);
    return s.length ? (s[Math.floor(s.length / 2)] as number) : 0;
  };
  const medRatio = median(points.map((p) => (p.drafted > 0 ? p.injured / p.drafted : 0)));
  const medDrafted = median(points.map((p) => p.drafted));
  const medSnapsPer = median(points.map((p) => (p.drafted > 0 ? p.snaps / p.drafted : 0)));
  points.forEach((p) => {
    const incomplete = medRatio > 0 && p.drafted > 0 && p.injured / p.drafted < 0.6 * medRatio;
    const shallow = medDrafted > 0 && p.drafted < 0.6 * medDrafted;
    const thinSnaps = hasSnaps && medSnapsPer > 0 && p.snaps > 0 && p.snaps / p.drafted < 0.75 * medSnapsPer;
    p.partial = incomplete || shallow || thinSnaps;
  });
  const partialSeasons = points.filter((p) => p.partial).map((p) => p.season);

  const fit = ((): TrendFit | null => {
    const val = (p: TrendPoint) => (hasSnaps ? p.stdRate : p.stdPct);
    const pts = points.filter((p) => val(p) > 0 && !p.partial);
    const n = pts.length;
    if (n < 3) return null;
    const xs = pts.map((p) => Number(p.season));
    const ys = pts.map((p) => Math.log(val(p)));
    const mx = xs.reduce((a, b) => a + b, 0) / n;
    const my = ys.reduce((a, b) => a + b, 0) / n;
    let sxx = 0;
    let sxy = 0;
    xs.forEach((x, i) => {
      sxx += (x - mx) ** 2;
      sxy += (x - mx) * ((ys[i] as number) - my);
    });
    const b = sxy / sxx;
    const a = my - b * mx;
    let sse = 0;
    xs.forEach((x, i) => {
      const r = (ys[i] as number) - (a + b * x);
      sse += r * r;
    });
    const seSlope = Math.sqrt(sse / (n - 2) / sxx);
    const t = seSlope > 0 ? b / seSlope : 0;
    const p = 2 * (1 - normalCdf(Math.abs(t)));
    return { annualPct: (Math.exp(b) - 1) * 100, totalPct: (Math.exp(b * ((xs[n - 1] as number) - (xs[0] as number))) - 1) * 100, p, firstYear: xs[0] as number, lastYear: xs[n - 1] as number };
  })();

  return { points, fit, partialSeasons, hasSnaps };
}

/* --------------------------------------------------------- season metrics */

export interface SeasonMetric {
  season: string;
  episodes: number;
  players: number;
  meanGm: number;
  medianGm: number;
  pctEnding: number;
  pct2: number;
  pct4: number;
  pct8: number;
  fantasyLost: number;
}

/** Per-season summary metrics (all seasons, ADP-filtered, not min-games gated). */
export function seasonMetrics(data: InjuryImpactData, adpRange: [number, number]): SeasonMetric[] {
  const [adpLo, adpHi] = adpRange;
  const fullAdp = adpLo === ADP_MIN && adpHi === ADP_MAX;
  const inRange = (adp: number | null) => (adp == null ? fullAdp : adp >= adpLo && adp <= adpHi);
  const bySeason: Record<number, { gm: number[]; ending: number; fantasy: number; players: Set<string> }> = {};
  data.player_injury_impacts.forEach((p) => {
    if (!inRange(p.overall_adp) || regGm(p) <= 0) return;
    const b = (bySeason[p.season] ??= { gm: [], ending: 0, fantasy: 0, players: new Set() });
    b.gm.push(regGm(p));
    if (p.season_ending) b.ending += 1;
    b.fantasy += p.net_value_lost;
    b.players.add(p.player);
  });
  const median = (arr: number[]) => {
    if (!arr.length) return 0;
    const s = [...arr].sort((a, b) => a - b);
    const m = Math.floor(s.length / 2);
    return s.length % 2 ? (s[m] as number) : ((s[m - 1] as number) + (s[m] as number)) / 2;
  };
  return Object.keys(bySeason)
    .map(Number)
    .sort((a, b) => a - b)
    .map((s) => {
      const b = bySeason[s] as { gm: number[]; ending: number; fantasy: number; players: Set<string> };
      const n = b.gm.length;
      const share = (k: number) => (n ? Math.round((b.gm.filter((g) => g >= k).length / n) * 1000) / 10 : 0);
      return {
        season: s.toString(),
        episodes: n,
        players: b.players.size,
        meanGm: n ? Math.round((b.gm.reduce((x, y) => x + y, 0) / n) * 10) / 10 : 0,
        medianGm: median(b.gm),
        pctEnding: n ? Math.round((b.ending / n) * 1000) / 10 : 0,
        pct2: share(2),
        pct4: share(4),
        pct8: share(8),
        fantasyLost: Math.round(b.fantasy),
      };
    });
}

/* ---------------------------------------------------------- region heatmap */

export interface RegionHeatmap {
  seasons: string[];
  rows: { region: string; cells: { season: string; rate: number }[]; avg: number }[];
  max: number;
  colTotals: { season: string; rate: number }[];
  grandRate: number;
}

/** Season x body-region heatmap: injuries per 1,000 drafted player-seasons. */
export function regionHeatmap(data: InjuryImpactData, adpRange: [number, number]): RegionHeatmap | null {
  if (!data.drafted_pool) return null;
  const [adpLo, adpHi] = adpRange;
  const fullAdp = adpLo === ADP_MIN && adpHi === ADP_MAX;
  const inRange = (adp: number | null) => (adp == null ? fullAdp : adp >= adpLo && adp <= adpHi);
  const draftedBySeason: Record<string, number> = {};
  data.drafted_pool.forEach((r) => {
    if (inRange(r.overall_adp)) draftedBySeason[r.season] = (draftedBySeason[r.season] || 0) + 1;
  });
  const seasons = Object.keys(draftedBySeason).sort();
  const counts: Record<string, Record<string, number>> = {};
  data.player_injury_impacts.forEach((p) => {
    if (!inRange(p.overall_adp) || regGm(p) <= 0) return;
    const reg = bodyRegion(p.injury);
    (counts[reg] ??= {})[p.season] = ((counts[reg] ??= {})[p.season] || 0) + 1;
  });
  const regions = BODY_REGION_ORDER.filter((r) => counts[r]);
  const totalDrafted = seasons.reduce((s, y) => s + (draftedBySeason[y] || 0), 0);
  let max = 0;
  const rows = regions.map((reg) => {
    const cells = seasons.map((s) => {
      const den = draftedBySeason[s] || 0;
      const rate = den > 0 ? ((counts[reg]?.[Number(s)] || 0) / den) * 1000 : 0;
      if (rate > max) max = rate;
      return { season: s, rate: Math.round(rate * 10) / 10 };
    });
    const regTotal = seasons.reduce((sum, s) => sum + (counts[reg]?.[Number(s)] || 0), 0);
    const avg = totalDrafted > 0 ? Math.round((regTotal / totalDrafted) * 1000 * 10) / 10 : 0;
    return { region: reg, cells, avg };
  });
  const colTotals = seasons.map((s) => {
    const den = draftedBySeason[s] || 0;
    const injuries = regions.reduce((sum, reg) => sum + (counts[reg]?.[Number(s)] || 0), 0);
    return { season: s, rate: den > 0 ? Math.round((injuries / den) * 1000 * 10) / 10 : 0 };
  });
  const grandInjuries = regions.reduce((sum, reg) => sum + seasons.reduce((s2, y) => s2 + (counts[reg]?.[Number(y)] || 0), 0), 0);
  const grandRate = totalDrafted > 0 ? Math.round((grandInjuries / totalDrafted) * 1000 * 10) / 10 : 0;
  return { seasons, rows, max, colTotals, grandRate };
}

/* --------------------------------------------------------- workload rates */

export interface WorkloadRate {
  position: string;
  unitLabel: string;
  injPerSnap: number | null;
  injPerUnit: number | null;
  gmPerUnit: number | null;
}

/** Each position paired with its natural exposure unit. Full pool, all seasons. */
export function workloadRates(data: InjuryImpactData, exposure: ExposureEntry[] | null): WorkloadRate[] | null {
  if (!exposure) return null;
  const UNIT: Record<string, { key: "pass_attempts" | "touches" | "targets"; label: string }> = {
    QB: { key: "pass_attempts", label: "pass att" },
    RB: { key: "touches", label: "touches" },
    WR: { key: "targets", label: "targets" },
    TE: { key: "targets", label: "targets" },
  };
  const ep: Record<string, number> = {};
  const gm: Record<string, number> = {};
  data.player_injury_impacts.forEach((p) => {
    if (regGm(p) <= 0) return;
    ep[p.position] = (ep[p.position] || 0) + 1;
    gm[p.position] = (gm[p.position] || 0) + regGm(p);
  });
  const snaps: Record<string, number> = {};
  const unitTot: Record<string, number> = {};
  exposure.forEach((e) => {
    snaps[e.position] = (snaps[e.position] || 0) + ((e.reg_snaps ?? e.snaps) || 0);
    const u = UNIT[e.position]?.key;
    const ex = e as unknown as Record<string, number | undefined>;
    if (u) unitTot[e.position] = (unitTot[e.position] || 0) + ((ex[`reg_${u}`] ?? ex[u]) || 0);
  });
  const rows: WorkloadRate[] = POS4.filter((pos) => UNIT[pos] && snaps[pos]).map((pos) => {
    const u = unitTot[pos] || 0;
    return {
      position: pos,
      unitLabel: (UNIT[pos] as { label: string }).label,
      injPerSnap: (snaps[pos] as number) > 0 ? ((ep[pos] || 0) / (snaps[pos] as number)) * 1000 : null,
      injPerUnit: u > 0 ? ((ep[pos] || 0) / u) * 1000 : null,
      gmPerUnit: u > 0 ? ((gm[pos] || 0) / u) * 1000 : null,
    };
  });
  return rows.length ? rows : null;
}

/* -------------------------------------------------------- position impact */

export interface PositionImpactRow {
  position: string;
  total_drafted: number;
  injuries: number;
  injury_rate: number | null;
  players_injured: number;
  games_missed: number;
  pct_games_missed: number;
  points_lost: number;
  avg_loss: number;
  severe_rate: number;
}

/** Injury volume vs fantasy impact per position, over the filtered sample. */
export function positionImpact(filtered: PlayerInjuryImpact[], drafted: Record<string, number>): PositionImpactRow[] {
  const POS_ORDER = ["RB", "WR", "QB", "TE"];
  const grouped: Record<string, { position: string; injuries: number; players: Set<string>; games_missed: number; reg_games_missed: number; points_lost: number; severe: number }> = {};
  filtered.forEach((p) => {
    if (!grouped[p.position]) {
      grouped[p.position] = { position: p.position, injuries: 0, players: new Set(), games_missed: 0, reg_games_missed: 0, points_lost: 0, severe: 0 };
    }
    const g = grouped[p.position] as (typeof grouped)[string];
    g.injuries += 1;
    g.players.add(`${p.player}|${p.season}`);
    g.games_missed += p.games_missed;
    g.reg_games_missed += regGm(p);
    g.points_lost += p.estimated_points_lost;
    if (p.impact_label === "Severe") g.severe += 1;
  });
  return Object.values(grouped)
    .map((g) => {
      const totalDrafted = drafted[g.position] || 0;
      return {
        position: g.position,
        total_drafted: totalDrafted,
        injuries: g.injuries,
        injury_rate: totalDrafted > 0 ? Math.round((g.players.size / totalDrafted) * 100) : null,
        players_injured: g.players.size,
        games_missed: g.games_missed,
        pct_games_missed: totalDrafted > 0 ? Math.round((g.reg_games_missed / (totalDrafted * GAMES_PER_SEASON)) * 100) : 0,
        points_lost: -Math.round(g.points_lost),
        avg_loss: g.injuries > 0 ? -(g.points_lost / g.injuries) : 0,
        severe_rate: g.injuries > 0 ? Math.round((g.severe / g.injuries) * 100) : 0,
      };
    })
    .sort((a, b) => {
      const ai = POS_ORDER.indexOf(a.position);
      const bi = POS_ORDER.indexOf(b.position);
      if (ai !== -1 && bi !== -1) return ai - bi;
      if (ai !== -1) return -1;
      if (bi !== -1) return 1;
      return a.position.localeCompare(b.position);
    });
}

export const POSITION_SORT_ACCESSORS: Record<string, (r: PositionImpactRow) => number | string> = {
  position: (r) => r.position,
  total_drafted: (r) => r.total_drafted,
  injuries: (r) => r.injuries,
  players_injured: (r) => r.players_injured,
  injury_rate: (r) => r.injury_rate ?? -1,
  games_missed: (r) => r.games_missed,
  pct_games_missed: (r) => r.pct_games_missed,
  points_lost: (r) => Math.abs(r.points_lost),
  avg_loss: (r) => Math.abs(r.avg_loss),
  severe_rate: (r) => r.severe_rate,
};

/* ------------------------------------------------------ injury type table */

export interface InjuryTypeRow {
  type: string;
  category: string;
  count: number;
  games_missed: number;
  avg_games_missed: number;
  points_lost: number;
  avg_loss: number;
  most_affected_pos: string;
}

/** Pattern view across cleaned injury types; the toolbar's Position re-scopes the whole breakdown. */
export function injuryTypeBreakdown(filtered: PlayerInjuryImpact[], injuryPos: string): InjuryTypeRow[] {
  const grouped: Record<string, { type: string; category: string; count: number; games_missed: number; points_lost: number; posCount: Record<string, number> }> = {};
  const scoped = injuryPos === "all" ? filtered : filtered.filter((p) => p.position === injuryPos);
  scoped.forEach((p) => {
    const type = cleanInjuryLabel(p.injury);
    if (!grouped[type]) grouped[type] = { type, category: categorizeInjury(type), count: 0, games_missed: 0, points_lost: 0, posCount: {} };
    const g = grouped[type] as (typeof grouped)[string];
    g.count += 1;
    g.games_missed += p.games_missed;
    g.points_lost += p.estimated_points_lost;
    g.posCount[p.position] = (g.posCount[p.position] || 0) + 1;
  });
  return Object.values(grouped)
    .map((g) => {
      const max = Math.max(...Object.values(g.posCount));
      const topPositions = Object.keys(g.posCount)
        .filter((pos) => g.posCount[pos] === max)
        .sort((a, b) => a.localeCompare(b));
      return {
        type: g.type,
        category: g.category,
        count: g.count,
        games_missed: g.games_missed,
        avg_games_missed: g.count > 0 ? g.games_missed / g.count : 0,
        points_lost: -Math.round(g.points_lost),
        avg_loss: g.count > 0 ? -(g.points_lost / g.count) : 0,
        most_affected_pos: topPositions.join(" / "),
      };
    })
    .sort((a, b) => b.count - a.count || a.points_lost - b.points_lost);
}

export function injuryCategoryOptions(rows: InjuryTypeRow[]): string[] {
  return Array.from(new Set(rows.map((r) => r.category))).sort();
}

export function injuryTypeVisible(rows: InjuryTypeRow[], category: string, search: string): InjuryTypeRow[] {
  const q = search.trim().toLowerCase();
  return rows.filter((r) => (category === "all" || r.category === category) && (q === "" || r.type.toLowerCase().includes(q)));
}

export interface InjuryTypeDisplay {
  rows: InjuryTypeRow[];
  other: InjuryTypeRow | null;
  hiddenCount: number;
}

/** The top N types, the long tail rolled into one "All Other Injury Types" row. */
export function injuryTypeDisplay(visible: InjuryTypeRow[], showAll: boolean): InjuryTypeDisplay {
  if (showAll || visible.length <= INJURY_TOP_N) return { rows: visible, other: null, hiddenCount: 0 };
  const rows = visible.slice(0, INJURY_TOP_N);
  const tail = visible.slice(INJURY_TOP_N);
  const count = tail.reduce((s, r) => s + r.count, 0);
  const games = tail.reduce((s, r) => s + r.games_missed, 0);
  const pointsLost = tail.reduce((s, r) => s + r.points_lost, 0);
  const other: InjuryTypeRow = {
    type: "All Other Injury Types",
    category: "Other",
    count,
    games_missed: games,
    avg_games_missed: count > 0 ? games / count : 0,
    points_lost: pointsLost,
    avg_loss: count > 0 ? pointsLost / count : 0,
    most_affected_pos: "",
  };
  return { rows, other, hiddenCount: tail.length };
}

export const INJURY_SORT_ACCESSORS: Record<string, (r: InjuryTypeRow) => number | string> = {
  type: (r) => r.type,
  category: (r) => r.category,
  count: (r) => r.count,
  avg_games_missed: (r) => r.avg_games_missed,
  points_lost: (r) => Math.abs(r.points_lost),
  avg_loss: (r) => Math.abs(r.avg_loss),
  most_affected_pos: (r) => r.most_affected_pos,
};

/** The toolbar's Sort dropdown, mapped onto the column-sort state. */
export const INJ_SORT_MAP: Record<string, SortState> = {
  impact: { key: "points_lost", dir: "desc" },
  occurrences: { key: "count", dir: "desc" },
  avgGames: { key: "avg_games_missed", dir: "desc" },
  perInjury: { key: "avg_loss", dir: "desc" },
  name: { key: "type", dir: "asc" },
};

export function injurySortValue(sort: SortState): string {
  return Object.keys(INJ_SORT_MAP).find((k) => (INJ_SORT_MAP[k] as SortState).key === sort.key && (INJ_SORT_MAP[k] as SortState).dir === sort.dir) ?? "impact";
}

/** The single worst (largest-magnitude) loss in a column, by row key. */
export function worstOf<T>(rows: T[], value: (r: T) => number, key: (r: T) => string): string | null {
  return (
    rows.reduce<{ k: string; v: number } | null>((best, r) => {
      const v = Math.abs(value(r));
      return best === null || v > best.v ? { k: key(r), v } : best;
    }, null)?.k ?? null
  );
}

/** Positions present in the filtered sample, for the toolbar's Position dropdown. */
export function injuryPosOptions(filtered: PlayerInjuryImpact[]): string[] {
  return POS4.filter((p) => filtered.some((fp) => fp.position === p));
}

/* ------------------------------------------------------- additional charts */

export interface SeasonSeries {
  season: string;
  [key: string]: number | string;
}

/** Games Missed by Position per Year. */
export function chart1Data(filtered: PlayerInjuryImpact[]): SeasonSeries[] {
  const grouped: Record<string, SeasonSeries> = {};
  filtered.forEach((p) => {
    if (!grouped[p.season]) grouped[p.season] = { season: p.season.toString(), QB: 0, RB: 0, WR: 0, TE: 0 };
    const row = grouped[p.season] as SeasonSeries;
    row[p.position] = ((row[p.position] as number) ?? 0) + p.games_missed;
  });
  return Object.values(grouped).sort((a, b) => a.season.localeCompare(b.season));
}

export const ADP_TIERS = ["Elite", "Early", "Mid", "Late", "Deep"] as const;

/** Injuries by ADP Tier per Season. */
export function chart2Data(filtered: PlayerInjuryImpact[]): SeasonSeries[] {
  const grouped: Record<string, SeasonSeries> = {};
  filtered.forEach((p) => {
    if (!grouped[p.season]) grouped[p.season] = { season: p.season.toString(), Elite: 0, Early: 0, Mid: 0, Late: 0, Deep: 0, "Undrafted/Unknown": 0 };
    const row = grouped[p.season] as SeasonSeries;
    if (row[p.adp_tier] !== undefined) row[p.adp_tier] = (row[p.adp_tier] as number) + 1;
  });
  return Object.values(grouped).sort((a, b) => a.season.localeCompare(b.season));
}

function draftedBySeasonPos(data: InjuryImpactData, f: Filters): Record<string, Record<string, number>> {
  const [adpLo, adpHi] = f.adp;
  const fullAdpRange = adpLo === ADP_MIN && adpHi === ADP_MAX;
  const drafted: Record<string, Record<string, number>> = {};
  data.drafted_pool.forEach((r) => {
    if (f.season !== "All" && r.season.toString() !== f.season) return;
    if (r.overall_adp == null) {
      if (!fullAdpRange) return;
    } else if (r.overall_adp < adpLo || r.overall_adp > adpHi) {
      return;
    }
    const s = r.season.toString();
    if (!drafted[s]) drafted[s] = {};
    (drafted[s] as Record<string, number>)[r.position] = ((drafted[s] as Record<string, number>)[r.position] || 0) + 1;
  });
  return drafted;
}

/** Average games missed per drafted player (non-injured included), by position per year. */
export function avgGamesMissedData(data: InjuryImpactData, f: Filters, filtered: PlayerInjuryImpact[]): SeasonSeries[] {
  if (!data.drafted_pool) return [];
  const drafted = draftedBySeasonPos(data, f);
  const missed: Record<string, Record<string, number>> = {};
  filtered.forEach((p) => {
    const s = p.season.toString();
    if (!missed[s]) missed[s] = {};
    (missed[s] as Record<string, number>)[p.position] = ((missed[s] as Record<string, number>)[p.position] || 0) + p.games_missed;
  });
  return Object.keys(drafted)
    .sort((a, b) => a.localeCompare(b))
    .map((s) => {
      const row: SeasonSeries = { season: s };
      POS4.forEach((pos) => {
        const den = (drafted[s] as Record<string, number>)[pos] || 0;
        const num = missed[s]?.[pos] || 0;
        row[pos] = den > 0 ? Math.round((num / den) * 10) / 10 : 0;
      });
      return row;
    });
}

/** Injury rate (% of drafted players injured) by position per year. */
export function injuryRateData(data: InjuryImpactData, f: Filters, filtered: PlayerInjuryImpact[]): SeasonSeries[] {
  if (!data.drafted_pool) return [];
  const drafted = draftedBySeasonPos(data, f);
  const injured: Record<string, Record<string, Set<string>>> = {};
  filtered.forEach((p) => {
    const s = p.season.toString();
    if (!injured[s]) injured[s] = {};
    const bs = injured[s] as Record<string, Set<string>>;
    if (!bs[p.position]) bs[p.position] = new Set();
    (bs[p.position] as Set<string>).add(p.player);
  });
  return Object.keys(drafted)
    .sort((a, b) => a.localeCompare(b))
    .map((s) => {
      const row: SeasonSeries = { season: s };
      POS4.forEach((pos) => {
        const den = (drafted[s] as Record<string, number>)[pos] || 0;
        const num = injured[s]?.[pos]?.size || 0;
        row[pos] = den > 0 ? Math.round((num / den) * 1000) / 10 : 0;
      });
      return row;
    });
}

export interface ScatterPoint {
  name: string;
  adp: number;
  games_missed: number;
  points_lost: number;
  position: string;
}

/** The ADP vs games-missed scatter, one point per filtered injury. */
export function chart4Data(filtered: PlayerInjuryImpact[]): ScatterPoint[] {
  return filtered.map((p) => ({ name: p.player, adp: p.overall_adp, games_missed: p.games_missed, points_lost: p.estimated_points_lost, position: p.position }));
}

/* ------------------------------------------------------ executive summary */

export interface ExecSummary {
  heavyInj: number | undefined;
  lightInj: number | undefined;
  priorInj: number | undefined;
  noPriorInj: number | undefined;
  workloadSig: boolean;
  retAll: number | null | undefined;
  retRB: number | null | undefined;
  retQB: number | null | undefined;
  trendFit: TrendFit | null;
  trendSignificant: boolean;
  trendRising: boolean;
  regressionAgrees: boolean | null;
}

export function execSummary(trends: SeasonTrends | null, aw: AgingWorkload | null, postReturn: PostReturnData | null, regression: InjuryRegression | null): ExecSummary {
  const trendFit = trends?.fit ?? null;
  return {
    heavyInj: aw?.workloadStats?.[2]?.injPct,
    lightInj: aw?.workloadStats?.[0]?.injPct,
    priorInj: aw?.priorClean?.prior?.injPct,
    noPriorInj: aw?.priorClean?.noPrior?.injPct,
    workloadSig: aw?.workloadSignal?.significant ?? false,
    retAll: postReturn?.overall?.median_return_ratio,
    retRB: postReturn?.byPosition?.find((p) => p.key === "RB")?.median_return_ratio,
    retQB: postReturn?.byPosition?.find((p) => p.key === "QB")?.median_return_ratio,
    trendFit,
    trendSignificant: trendFit ? trendFit.p < 0.05 && trendFit.annualPct < 0 : false,
    trendRising: trendFit ? trendFit.p < 0.05 && trendFit.annualPct > 0 : false,
    regressionAgrees: regression ? regression.season_trend.p < 0.05 : null,
  };
}

/* ------------------------------------------------------------ tag impact */

export interface TagBar {
  g: TagGroup;
  name: string;
  value: number;
  text: string;
}

export function tagStatus(data: TagImpactData, k: string): TagGroup | undefined {
  return data.by_status.find((g) => g.key === k);
}

export function tagCell(data: TagImpactData, k: string): TagGroup | undefined {
  return data.matrix.find((g) => g.key === k);
}

export const TAG_DECISION_KEYS = ["Questionable|DNP", "Questionable|Limited", "Questionable|Full", "None|DNP", "None|Limited", "None|Full"];

export const pctOf = (v: number | null | undefined): string => (v == null ? "-" : `${Math.round(v * 100)}%`);
export const signedOf = (v: number | null | undefined): string => (v == null ? "-" : `${v > 0 ? "+" : ""}${v}`);

/** The gameday tags a manager has to decide on. */
export function tagBars(data: TagImpactData): TagBar[] {
  return TAG_DECISION_KEYS.map((k) => tagCell(data, k))
    .filter((g): g is TagGroup => !!g && g.expected_ratio != null)
    .map((g) => ({ g, name: g.label.replace("Listed, no designation", "No designation"), value: Math.round((g.expected_ratio as number) * 100), text: pctOf(g.expected_ratio) }));
}

/* ------------------------------------------------------------- draft sim */

export const STRAT_COLORS: Record<string, string> = {
  rb_rb: "#16A34A",
  wr_wr: "#2563EB",
  hero_rb: "#059669",
  zero_rb: "#7C3AED",
  early_te: "#B8901C",
  early_qb: "#DC2626",
  balanced: "#0b1f3a",
  robust_rb: "#F97316",
  superflex_qb: "#DB2777",
};

export type SimSortKey = keyof StrategyResult;
export type SimTrendMetric = "playoff_rate" | "mean_points" | "cvar10";

export interface SimState {
  model: ReplacementModelKey;
  hidden: string[];
  sortKey: SimSortKey;
  trendMetric: SimTrendMetric;
}

export const DEFAULT_SIM_STATE: SimState = { model: "normal", hidden: [], sortKey: "mean_points", trendMetric: "mean_points" };

export interface SimRow {
  key: string;
  label: string;
  description: string;
  r: StrategyResult | undefined;
}

const SMALLER_BETTER = ["avg_starter_weeks_lost", "avg_vorp_lost", "avg_waiver_pickups", "p_both_top2_miss4", "p_lose_2_starters", "p_lose_3plus_starters"];

export function simRows(data: DraftSimData, state: SimState): SimRow[] {
  const modelResults = data.results[state.model] ?? {};
  const arr: SimRow[] = data.strategies.map((s) => ({ ...s, r: modelResults[s.key] }));
  arr.sort((a, b) => {
    const av = (a.r?.[state.sortKey] as number) ?? 0;
    const bv = (b.r?.[state.sortKey] as number) ?? 0;
    return SMALLER_BETTER.includes(state.sortKey as string) ? av - bv : bv - av;
  });
  return arr;
}

export function simCdf(data: DraftSimData, model: ReplacementModelKey): Record<string, number>[] {
  const modelResults = data.results[model] ?? {};
  const anyKey = data.strategies[0]?.key ?? "";
  const grid = modelResults[anyKey]?.cdf ?? [];
  return grid.map((pt, i) => {
    const row: Record<string, number> = { x: pt.x };
    for (const s of data.strategies) row[s.key] = (modelResults[s.key]?.cdf[i]?.p ?? 0) * 100;
    return row;
  });
}

export function simLoss(rows: SimRow[]): { label: string; key: string; "≥1 starter": number; "≥2 starters": number; "≥3 starters": number }[] {
  return rows.map((row) => ({
    label: row.label,
    key: row.key,
    "≥1 starter": row.r ? row.r.p_lose_1_starter * 100 : 0,
    "≥2 starters": row.r ? row.r.p_lose_2_starters * 100 : 0,
    "≥3 starters": row.r ? row.r.p_lose_3plus_starters * 100 : 0,
  }));
}

export function simScatter(data: DraftSimData, model: ReplacementModelKey): { key: string; label: string; x: number; y: number }[] {
  const modelResults = data.results[model] ?? {};
  return data.strategies.filter((s) => modelResults[s.key]).map((s) => ({ key: s.key, label: s.label, x: (modelResults[s.key] as StrategyResult).cvar10, y: (modelResults[s.key] as StrategyResult).mean_points }));
}

export function simAcrossModels(data: DraftSimData): Record<string, number | string>[] {
  return data.meta.replacement_models.map((m) => {
    const row: Record<string, number | string> = { model: m.label };
    for (const s of data.strategies) row[s.key] = data.results[m.key]?.[s.key]?.mean_points ?? 0;
    return row;
  });
}

export function simTrend(data: DraftSimData, model: ReplacementModelKey, metric: SimTrendMetric): Record<string, number>[] {
  const bySeason = data.results_by_season[model] ?? {};
  return data.meta.seasons.map((yr) => {
    const row: Record<string, number> = { season: yr };
    for (const s of data.strategies) {
      const pt = (bySeason[s.key] ?? []).find((p) => p.season === yr);
      if (pt) row[s.key] = metric === "playoff_rate" ? pt.playoff_rate * 100 : pt[metric];
    }
    return row;
  });
}

export function simLabelFor(data: DraftSimData, key: string): string {
  return data.strategies.find((s) => s.key === key)?.label ?? key;
}

/* ------------------------------------------------------------ formatting */

export const fmtInt = (n: number): string => Math.round(n).toLocaleString("en-US");
export const fmt1 = (n: number): string => n.toLocaleString("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
export const fmt2 = (n: number): string => n.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
export const pct0 = (v: number | null | undefined): string => (v == null ? "-" : `${Math.round(v)}%`);
/** "RBs in Rounds 3-4" but "WRs at Picks 13-24". */
export const slotPrep = (bucket: string): string => (bucket.startsWith("Pick") ? "at" : "in");
